sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        // 验证请求
        if (!request.getHeader('X-userToken') && !gs.getSession().isLoggedIn()) {
            response.setStatus(401);
            response.setBody('Authentication required');
            return;
        }

        var sysId = request.pathParams.sys_id;
        var gr = new GlideRecord('x_1770592_easy_t_0_my_asset_request');

        if (!gr.get(sysId)) {
            response.setStatus(404);
            response.setBody('Record not found');
            return;
        }

        // 生成PDF内容
        var html = generateHTMLContent(gr);
        var pdf = new PDFDocument(html);

        // 设置响应头
        response.setContentType('application/pdf');
        response.setHeader('Content-Disposition', 'attachment; filename="AssetRequest_' + sysId + '.pdf"');
        response.setBody(pdf.getStream());

    } catch (e) {
        gs.logError('Error in PDF generation API: ' + e, 'Generate PDF API');
        response.setStatus(500);
        response.setBody('Internal server error: ' + e.message);
    }

    function generateHTMLContent(gr) {
        // 返回你的HTML内容
        // 这里是你之前的内容生成逻辑
    }
})();
